final supabaseProvider = Provider<SupabaseClient>((ref) => Supabase.instance.client);
final apiProvider = Provider<TugonApi>((ref) => TugonApi(ref.watch(supabaseProvider)));
final queueProvider = Provider<OfflineReportQueue>((ref) => OfflineReportQueue());
final incidentsProvider = FutureProvider.autoDispose((ref) => ref.watch(apiProvider).myIncidents());

void main() async { WidgetsFlutterBinding.ensureInitialized(); await dotenv.load(fileName: '.env'); await Supabase.initialize(url: dotenv.env['SUPABASE_URL']!, anonKey: dotenv.env['SUPABASE_ANON_KEY']!); runApp(const ProviderScope(child: TugonApp())); }

class TugonApp extends ConsumerWidget { const TugonApp({super.key}); @override Widget build(BuildContext context, WidgetRef ref) { final router = GoRouter(refreshListenable: GoRouterRefreshStream(Supabase.instance.client.auth.onAuthStateChange), redirect: (_, state) { final signedIn = Supabase.instance.client.auth.currentSession != null; if (!signedIn && state.matchedLocation != '/login') return '/login'; if (signedIn && state.matchedLocation == '/login') return '/'; return null; }, routes: [GoRoute(path: '/login', builder: (_, __) => const LoginScreen()), GoRoute(path: '/', builder: (_, __) => const HomeScreen()), GoRoute(path: '/report', builder: (_, __) => const ReportScreen()), GoRoute(path: '/reports', builder: (_, __) => const ReportsScreen()), GoRoute(path: '/notifications', builder: (_, __) => const NotificationsScreen()), GoRoute(path: '/profile', builder: (_, __) => const ProfileScreen())]); return MaterialApp.router(title: 'TUGON', theme: tugonTheme(Brightness.light), darkTheme: tugonTheme(Brightness.dark), themeMode: ThemeMode.system, routerConfig: router, debugShowCheckedModeBanner: false); } }

class GoRouterRefreshStream extends ChangeNotifier { GoRouterRefreshStream(Stream<dynamic> stream) { stream.listen((_) => notifyListeners()); } }

