  @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Report incident', style: TextStyle(fontWeight: FontWeight.w800)), leading: IconButton(onPressed: () => context.pop(), icon: const Icon(Icons.arrow_back))), body: Form(key: formKey, child: ListView(padding: const EdgeInsets.fromLTRB(20, 4, 20, 32), children: [const Text('Tell us what happened', style: TextStyle(fontSize: 23, fontWeight: FontWeight.w800, color: TugonColors.navy)), const SizedBox(height: 7), const Text('Provide details so our response team can act quickly.', style: TextStyle(color: TugonColors.muted)), const SizedBox(height: 25), const SectionLabel(icon: Icons.report_problem_outlined, text: 'Incident information'), DropdownButtonFormField<String>(value: type, decoration: const InputDecoration(labelText: 'Incident type'), items: ['Flooding', 'Medical emergency', 'Fire', 'Landslide', 'Structural damage', 'Other'].map((value) => DropdownMenuItem(value: value, child: Text(value))).toList(), onChanged: (value) => setState(() => type = value!)), const SizedBox(height: 14), TextFormField(controller: description, maxLines: 4, validator: (value) => value == null || value.length < 10 ? 'Please add at least 10 characters.' : null, decoration: const InputDecoration(labelText: 'What happened?', hintText: 'Describe the situation and who needs help.')), const SizedBox(height: 25), const SectionLabel(icon: Icons.location_on_outlined, text: 'Location'), TextFormField(controller: location, validator: (value) => value == null || value.isEmpty ? 'Location is required.' : null, decoration: const InputDecoration(labelText: 'Barangay and location', hintText: 'e.g. Purok 4, Brgy. Pulong Niogan', prefixIcon: Icon(Icons.location_on_outlined))), const SizedBox(height: 25), const SectionLabel(icon: Icons.priority_high_rounded, text: 'Severity'), SegmentedButton<String>(segments: const [ButtonSegment(value: 'low', label: Text('Low')), ButtonSegment(value: 'medium', label: Text('Medium')), ButtonSegment(value: 'high', label: Text('High')), ButtonSegment(value: 'critical', label: Text('Critical'))], selected: {severity}, onSelectionChanged: (values) => setState(() => severity = values.first)), const SizedBox(height: 25), const SectionLabel(icon: Icons.photo_camera_outlined, text: 'Photo evidence'), OutlinedButton.icon(onPressed: () {}, icon: const Icon(Icons.add_a_photo_outlined), label: const Text('Add up to 5 photos')), const SizedBox(height: 30), SizedBox(height: 54, child: FilledButton.icon(onPressed: saving ? null : submit, icon: saving ? const SizedBox(width: 18, height: 18, child: CircularProgressIndicator(color: Colors.white, strokeWidth: 2)) : const Icon(Icons.send_rounded), label: Text(saving ? 'Sending…' : 'Submit report')))])); }
